source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((r, c) for r in range(h) for c in range(w) if grid[r][c] == 2)
    if r == 0:
        direction = (1, 0)
    elif r == h - 1:
        direction = (-1, 0)
    elif c == 0:
        direction = (0, 1)
    elif c == w - 1:
        direction = (0, -1)
    else:
        direction = (1, 0)

    queue = deque([(r, c, *direction)])
    seen = set()
    while queue:
        r, c, dr, dc = queue.popleft()
        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            continue
        if grid[nr][nc] != 8:
            if out[nr][nc] == 0:
                out[nr][nc] = 2
            queue.append((nr, nc, dr, dc))
            continue

        for pr, pc in ((-dc, dr), (dc, -dr)):
            rr, cc = r, c
            while True:
                if out[rr][cc] == 0:
                    out[rr][cc] = 2
                ar, ac = rr + dr, cc + dc
                if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] == 0:
                    if out[ar][ac] == 0:
                        out[ar][ac] = 2
                    queue.append((ar, ac, dr, dc))
                    break
                rr, cc = rr + pr, cc + pc
                if not (0 <= rr < h and 0 <= cc < w):
                    break
    return out
